-- New tables no longer reach anon or authenticated by default (0000_tenancy changed that); the
-- explicit revoke keeps the result independent of it.
REVOKE ALL ON public.settings, public.modules_enabled FROM anon, authenticated;
--> statement-breakpoint
GRANT SELECT, INSERT ON public.settings, public.modules_enabled TO app_runtime;
--> statement-breakpoint
-- Only the columns an owner edits can change. Who created a row, and when, cannot; nor can a row
-- be moved to another company. There is no DELETE.
