-- Every member reads their own company's settings and module switches: the header and the menu
-- are built from them. Only an owner writes them, and only as themselves.
CREATE POLICY settings_select ON public.settings FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()));
--> statement-breakpoint
CREATE POLICY settings_insert ON public.settings FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
CREATE POLICY settings_update ON public.settings FOR UPDATE TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) = 'owner')
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint

